const r = await tools.exec_command({
  cmd: "nvidia-smi --query-gpu=index,uuid,memory.used,memory.total,utilization.gpu --format=csv,noheader,nounits; nvidia-smi --query-compute-apps=gpu_uuid,pid,used_memory,process_name --format=csv,noheader,nounits; ps -eo pid,ppid,pgid,lstart,cmd --sort=pid | rg 'Track_1|track1|eval_embodied_agent|openpi|RL_env_benchmark' || true",
  workdir: "/data/fjy/worldarena",
  yield_time_ms: 10000,
  max_output_tokens: 16000,
  sandbox_permissions: "require_escalated",
  justification: "允许我检查 GPU1/GPU7 占用和对应进程身份，以便安全启动已冻结的 SSE14 数据采集吗？"
});
text(r.output);

const r = await tools.exec_command({
  cmd: "kill -TERM -- -1974219; for i in 1 2 3 4 5; do nvidia-smi --id=7 --query-gpu=index,memory.used,utilization.gpu --format=csv,noheader,nounits; if ! ps -g 1974219 -o pid=,pgid=,cmd= | rg -q .; then break; fi; sleep 2; done; ps -g 1974219 -o pid=,pgid=,cmd= || true",
  workdir: "/data/fjy/worldarena",
  yield_time_ms: 15000,
  max_output_tokens: 8000,
  sandbox_permissions: "require_escalated",
  justification: "允许我按你的既有授权终止已确认占用 GPU7 的官方 Track 1 进程组 1974219，从而启动当前 SSE14 实验吗？"
});
text(r.output);

